-- Sincronizzazione ufficiale GK-PRA-001 -> GK-PRA-036 da foglio "Sync App".
-- Aggiornamento conservativo: nessun INSERT in exercises e nessuna modifica a schema_url/foto_url.

alter table public.exercises add column if not exists schema_step_3 text;
alter table public.exercises add column if not exists schema_step_4 text;
alter table public.exercises add column if not exists schema_step_5 text;

insert into public.exercise_subcategories (id, category_id, nome, fase, attivo) values
  (145, 1, 'Deviazione con intervento attivo', 'Disturbo', true)
on conflict (category_id, nome, fase) do update
set attivo = excluded.attivo, updated_at = now();

-- Arresta la migration se manca anche uno solo dei 36 record o se esistono duplicati.
do $$
declare
  missing_codes text;
begin
  with expected(codice) as (values ('GK-PRA-001'), ('GK-PRA-002'), ('GK-PRA-003'), ('GK-PRA-004'), ('GK-PRA-005'), ('GK-PRA-006'), ('GK-PRA-007'), ('GK-PRA-008'), ('GK-PRA-009'), ('GK-PRA-010'), ('GK-PRA-011'), ('GK-PRA-012'), ('GK-PRA-013'), ('GK-PRA-014'), ('GK-PRA-015'), ('GK-PRA-016'), ('GK-PRA-017'), ('GK-PRA-018'), ('GK-PRA-019'), ('GK-PRA-020'), ('GK-PRA-021'), ('GK-PRA-022'), ('GK-PRA-023'), ('GK-PRA-024'), ('GK-PRA-025'), ('GK-PRA-026'), ('GK-PRA-027'), ('GK-PRA-028'), ('GK-PRA-029'), ('GK-PRA-030'), ('GK-PRA-031'), ('GK-PRA-032'), ('GK-PRA-033'), ('GK-PRA-034'), ('GK-PRA-035'), ('GK-PRA-036'))
  select string_agg(expected.codice, ', ' order by expected.codice)
    into missing_codes
  from expected
  left join public.exercises e on e.codice = expected.codice and e.category_id = 1
  where e.id is null;

  if missing_codes is not null then
    raise exception 'Sincronizzazione annullata. Codici mancanti o fuori categoria: %', missing_codes;
  end if;

  if exists (
    with expected(codice) as (values ('GK-PRA-001'), ('GK-PRA-002'), ('GK-PRA-003'), ('GK-PRA-004'), ('GK-PRA-005'), ('GK-PRA-006'), ('GK-PRA-007'), ('GK-PRA-008'), ('GK-PRA-009'), ('GK-PRA-010'), ('GK-PRA-011'), ('GK-PRA-012'), ('GK-PRA-013'), ('GK-PRA-014'), ('GK-PRA-015'), ('GK-PRA-016'), ('GK-PRA-017'), ('GK-PRA-018'), ('GK-PRA-019'), ('GK-PRA-020'), ('GK-PRA-021'), ('GK-PRA-022'), ('GK-PRA-023'), ('GK-PRA-024'), ('GK-PRA-025'), ('GK-PRA-026'), ('GK-PRA-027'), ('GK-PRA-028'), ('GK-PRA-029'), ('GK-PRA-030'), ('GK-PRA-031'), ('GK-PRA-032'), ('GK-PRA-033'), ('GK-PRA-034'), ('GK-PRA-035'), ('GK-PRA-036'))
    select e.codice
    from public.exercises e join expected on expected.codice = e.codice
    group by e.codice having count(*) <> 1
  ) then
    raise exception 'Sincronizzazione annullata: rilevati codici duplicati.';
  end if;
end $$;

with official (
